namespace NThingMap {
long MaxLayers = 3;
long MaxLayerCellSize = 5000;
extern const CLayerInfo LayerInfo[7] = { {2, 1}, {8, 2}, {4, 3}, {32, 5}, {64, 6}, {-1, 0}, {1000, 9} };
}

static int g_fail = 0;
